import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { LoaderContext } from 'astro/loaders';

import {
  draftNavigationConflicts,
  draftPaths,
  isPublished,
  PAGE_STATUSES,
  pageStatusSchema,
  parsePageStatus,
  publishedOnly,
  renderDocs7Ignore,
} from '../../src/content/publication.ts';

const HEADER = [
  '# Generated by `pnpm docs7:ignore`; do not edit by hand.',
  '# Pages whose frontmatter status is not "published" are not uploaded to Docs7.',
];

describe('page status', () => {
  it('defaults to draft when status is missing', () => {
    assert.deepEqual(PAGE_STATUSES, ['draft', 'published']);
    assert.equal(pageStatusSchema.parse(undefined), 'draft');
    assert.equal(pageStatusSchema.parse('draft'), 'draft');
    assert.equal(pageStatusSchema.parse('published'), 'published');
  });

  it('treats unknown or malformed status as draft', () => {
    const drafts = [
      undefined,
      null,
      {},
      { status: undefined },
      { status: null },
      { status: 'draft' },
      { status: 'Published' },
      { status: 'publish' },
      { status: true },
      { status: 1 },
      'published',
    ];
    for (const data of drafts) {
      assert.equal(isPublished(data), false, JSON.stringify(data) ?? String(data));
    }
  });

  it('publishes only the exact value', () => {
    assert.equal(isPublished({ status: 'published' }), true);
    assert.equal(isPublished({ title: 'A page', status: 'published' }), true);
  });

  it('rejects a status typo instead of defaulting it', () => {
    assert.equal(parsePageStatus(undefined), 'draft');
    assert.equal(parsePageStatus('published'), 'published');
    assert.throws(() => parsePageStatus('publish'), { name: 'ZodError' });
    const draft = draftPaths([{ path: 'blog/typo.mdx', data: { status: 'publish' } }]);
    assert.deepEqual(draft, ['blog/typo.mdx']);
  });
});

describe('draftPaths', () => {
  it('returns the paths of every page that is not published', () => {
    assert.deepEqual(
      draftPaths([
        { path: 'index.mdx', data: { status: 'published' } },
        { path: 'blog/hello.mdx', data: { status: 'draft' } },
        { path: 'blog/untitled.mdx', data: {} },
        { path: 'en/index.mdx', data: { status: 'published' } },
      ]),
      ['blog/hello.mdx', 'blog/untitled.mdx'],
    );
  });
});

describe('renderDocs7Ignore', () => {
  it('sorts and deduplicates paths below a fixed header', () => {
    const output = renderDocs7Ignore([
      'en/blog/draft.mdx',
      'blog/b.mdx',
      'blog/a.mdx',
      'blog/a.mdx',
    ]);

    assert.equal(output, [
      ...HEADER,
      'blog/a.mdx',
      'blog/b.mdx',
      'en/blog/draft.mdx',
      '',
    ].join('\n'));
    assert.ok(output.endsWith('\n'));
    assert.ok(output.includes('pnpm docs7:ignore'));
  });

  it('does not depend on input order and keeps Windows separators out', () => {
    const first = renderDocs7Ignore(['b.mdx', 'a.mdx']);
    const second = renderDocs7Ignore(['a.mdx', 'b.mdx']);
    assert.equal(first, second);
    assert.equal(
      renderDocs7Ignore(['blog\\draft.mdx']),
      renderDocs7Ignore(['blog/draft.mdx']),
    );
  });

  it('renders only the header when every page is published', () => {
    assert.equal(renderDocs7Ignore([]), [...HEADER, ''].join('\n'));
  });
});

describe('draftNavigationConflicts', () => {
  it('reports navigation entries that point at a draft', () => {
    assert.deepEqual(
      draftNavigationConflicts(
        ['index', 'about', 'blog/hello', 'en/index', 'en/about'],
        ['index.mdx', 'blog/hello.mdx', 'en/index.mdx'],
      ),
      ['index', 'blog/hello', 'en/index'],
    );
  });

  it('matches index pages without folding them into their directory', () => {
    // `index` is the root page, not the content root directory, and `en/index`
    // is a page inside the English directory, not the directory itself.
    assert.deepEqual(draftNavigationConflicts(['index'], ['index.mdx']), ['index']);
    assert.deepEqual(draftNavigationConflicts(['en/index'], ['en/index.mdx']), ['en/index']);
    assert.deepEqual(draftNavigationConflicts(['en'], ['en/index.mdx']), []);
  });

  it('keeps languages apart', () => {
    assert.deepEqual(draftNavigationConflicts(['about'], ['en/about.mdx']), []);
    assert.deepEqual(draftNavigationConflicts(['en/about'], ['en/about.mdx']), ['en/about']);
  });
});

interface FakeEntry {
  id: string;
  data: Record<string, unknown>;
}

function fakeStore(initial: FakeEntry[] = []) {
  const entries = new Map(initial.map((entry) => [entry.id, entry]));
  const store = {
    get: (id: string) => entries.get(id),
    entries: () => [...entries.entries()],
    set: (entry: FakeEntry): boolean => {
      entries.set(entry.id, entry);
      return true;
    },
    values: () => [...entries.values()],
    keys: () => [...entries.keys()],
    delete: (id: string) => { entries.delete(id); },
    clear: () => { entries.clear(); },
    has: (id: string) => entries.has(id),
    addModuleImport: () => {},
  };
  return { entries, store };
}

describe('publishedOnly', () => {
  it('drops drafts from the store before Astro reads routes', async () => {
    const { entries, store } = fakeStore([{ id: 'turned-draft', data: { status: 'published' } }]);
    const visibleWhileLoading: string[][] = [];

    const loader = publishedOnly({
      name: 'test-loader',
      async load(context) {
        context.store.set({ id: 'published', data: { status: 'published' } });
        context.store.set({ id: 'missing', data: { title: 'No status' } });
        context.store.set({ id: 'invalid', data: { status: 'publish' } });
        context.store.set({ id: 'turned-draft', data: { status: 'draft' } });
        visibleWhileLoading.push(context.store.keys().sort());
      },
    });

    await loader.load({ store } as unknown as LoaderContext);

    assert.deepEqual([...entries.keys()], ['published']);
    assert.deepEqual(visibleWhileLoading, [['published']]);
  });

  it('delegates every other store method', async () => {
    const { store } = fakeStore([{ id: 'published', data: { status: 'published' } }]);
    const seen: boolean[] = [];

    const loader = publishedOnly({
      name: 'test-loader',
      async load(context) {
        seen.push(context.store.has('published'));
        seen.push(context.store.has('missing'));
        context.store.delete('published');
        seen.push(context.store.has('published'));
      },
    });

    await loader.load({ store } as unknown as LoaderContext);
    assert.deepEqual(seen, [true, false, false]);
  });

  it('keeps the schema of the wrapped loader', () => {
    const loader = publishedOnly({
      name: 'test-loader',
      schema: pageStatusSchema,
      async load() {},
    });
    assert.ok('schema' in loader);
    assert.equal(loader.schema, pageStatusSchema);
  });
});
